      this.roughness = opts.roughness === undefined ? 0.6 : clamp(opts.roughness, 0, 1);
      this.specularColor = new Color(opts.specularColor === undefined ? 0xffffff : opts.specularColor);
      // PBR-lite inputs.  These are intentionally small approximations, not a
      // metallic-roughness BRDF: AO attenuates indirect fill, metalness trades
      // diffuse response for a stronger tinted stepped highlight, and detail is
      // a deterministic world-space pixel grain layered with the atlas sampler.
      this.ao = clamp(opts.ao === undefined ? 1 : opts.ao, 0, 1);
      this.metalness = clamp(opts.metalness === undefined ? 0 : opts.metalness, 0, 1);
      this.detail = clamp(opts.detail === undefined ? 0 : opts.detail, 0, 1);
