      // blend weight, so no per-material GPU texture is created.
      this.textureTile = opts.textureTile === undefined ? -1 : (opts.textureTile | 0);
      this.textureScale = opts.textureScale === undefined ? 1 : opts.textureScale;
      this.textureMix = clamp(opts.textureMix === undefined ? 0 : opts.textureMix, 0, 1);
      this.bump = opts.bump === undefined ? 0.88 : opts.bump;
      this.surfaceType = opts.surfaceType || 0;
      this.radiance = opts.radiance === undefined ? 1 : opts.radiance;
      this.viewModel = !!opts.viewModel;
      this.opacity = opts.opacity === undefined ? 1 : opts.opacity;
      this.transparent = !!opts.transparent;
      this.wireframe = !!opts.wireframe;
      this.unlit = !!opts.unlit;
      this.depthTest = opts.depthTest === undefined ? true : !!opts.depthTest;
      this.depthWrite = opts.depthWrite === undefined ? true : !!opts.depthWrite;
      this.blending = opts.blending || 'normal';
